const tabId = 787783793;

const accordionDetails = await browserjs(tabId, () => {
  // Let's click open all accordion elements
  const buttons = Array.from(document.querySelectorAll('button, summary, .accordion__title, [aria-expanded]'));
  for (const b of buttons) {
    if (b.textContent.includes('Specification') || b.textContent.includes('guarantee') || b.textContent.includes('suitable') || b.textContent.includes('Manuals')) {
      b.click();
    }
  }
  return {
    specs: document.querySelector('.specification, [data-accordion-content], #accordion-specification')?.innerText || 'Not found via selector',
    guarantee: Array.from(document.querySelectorAll('*')).filter(el => el.textContent.includes('Our guarantee') || el.textContent.includes('Extended Warranty')).map(e => e.innerText).slice(0, 5)
  };
});

// Let's wait a moment and then capture the text under Specification
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1000 });

const fullSpecText = await browserjs(tabId, () => {
  const allText = document.body.innerText;
  const specIndex = allText.indexOf("Specification");
  const guaranteeIndex = allText.indexOf("Our guarantee");
  return {
    specsSection: specIndex !== -1 ? allText.substring(specIndex, specIndex + 1500) : "No spec section",
    guaranteeSection: guaranteeIndex !== -1 ? allText.substring(guaranteeIndex, guaranteeIndex + 1000) : "No guarantee section"
  };
});

console.log("Specs Section:", fullSpecText.specsSection);
console.log("Guarantee Section:", fullSpecText.guaranteeSection);

