const tabId = 787784569;

const details = await browserjs(tabId, () => {
  // find price
  const price = document.querySelector('[itemprop="price"], .value, .sales, .price')?.textContent?.trim();

  // let's search for weight and dimensions
  const allText = document.body.innerText;
  const sections = Array.from(document.querySelectorAll('button, summary, h2, h3, div')).filter(el => {
    const t = el.textContent.toLowerCase();
    return t.includes('specifications') || t.includes('measurements') || t.includes('weight & dimension');
  });

  return {
    price,
    headings: sections.map(s => s.textContent.trim()).slice(0, 10),
    snippets: allText.match(/(?:weight|dimensions|folded|unfolded|underseat basket|capacity|suitable)[\s\S]{1,150}/gi)?.slice(0, 15)
  };
});

console.log("Bugaboo price & snippets:", details);

